DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='certrace_reporting') THEN CREATE ROLE certrace_reporting NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
GRANT USAGE ON SCHEMA reporting TO certrace_reporting;
GRANT SELECT,INSERT ON ALL TABLES IN SCHEMA reporting TO certrace_reporting;
GRANT UPDATE ON reporting.records, reporting.record_heads TO certrace_reporting;
GRANT certrace_reporting TO CURRENT_USER;
ALTER TABLE reporting.records ENABLE ROW LEVEL SECURITY;
ALTER TABLE reporting.records FORCE ROW LEVEL SECURITY;
CREATE POLICY record_owner ON reporting.records TO certrace_reporting USING (user_id = nullif(current_setting('certrace.user_id',true),'')::uuid) WITH CHECK (user_id = nullif(current_setting('certrace.user_id',true),'')::uuid);
ALTER TABLE reporting.record_heads ENABLE ROW LEVEL SECURITY;
ALTER TABLE reporting.record_heads FORCE ROW LEVEL SECURITY;
CREATE POLICY head_owner ON reporting.record_heads TO certrace_reporting USING(user_id=nullif(current_setting('certrace.user_id',true),'')::uuid) WITH CHECK(user_id=nullif(current_setting('certrace.user_id',true),'')::uuid);
CREATE FUNCTION reporting.guard_sealed_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.sealed OR to_jsonb(NEW)-'sealed' <> to_jsonb(OLD)-'sealed' OR NOT NEW.sealed THEN RAISE EXCEPTION 'Report revisions are immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER seal_record BEFORE UPDATE ON reporting.records FOR EACH ROW EXECUTE FUNCTION reporting.guard_sealed_record();
