CREATE FUNCTION reporting.guard_sealed_tree() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_table text:=TG_ARGV[0]; current_id uuid:=NEW._parent_id; next_table text; locked boolean;
BEGIN
 WHILE current_table <> 'records' LOOP
  SELECT parent_name INTO next_table FROM reporting.storage_tables WHERE name=current_table;
  IF next_table IS NULL THEN RAISE EXCEPTION 'Unknown parent relation'; END IF;
  EXECUTE format('SELECT _parent_id FROM reporting.%I WHERE _id=$1',current_table) INTO current_id USING current_id;
  current_table:=next_table;
 END LOOP;
 SELECT sealed INTO locked FROM reporting.records WHERE id=current_id FOR SHARE;
 IF locked IS DISTINCT FROM false THEN RAISE EXCEPTION 'Report revision is sealed or inaccessible' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
